import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.D46keoNO.js";const b=JSON.parse('{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1785141565000}'),i={name:"guide/index.md"};function l(o,t,s,h,n,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h1><p><strong>variable-translator</strong> 是一款 VSCode 插件，自动检测文件路径或选中文本中的任意非英文字符（中文、日文、韩文、俄文等），并将其翻译为符合命名规范的英文。</p><p>写代码时想好了中文名却卡在英文命名？直接输入中文，让插件帮你翻译成 <code>camelCase</code>、<code>snake_case</code> 等 8 种命名格式。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>触发方式</th><th>说明</th></tr></thead><tbody><tr><td>文件路径翻译</td><td>右键新建文件/文件夹</td><td>自动检测路径中的非英文字符并翻译创建</td></tr><tr><td>选中文本翻译</td><td><code>Alt+Shift+T</code></td><td>翻译并替换选中文本</td></tr><tr><td>翻译并复制</td><td><code>Alt+Shift+C</code></td><td>翻译结果按多种格式写入剪贴板历史</td></tr><tr><td>撤回翻译</td><td><code>Alt+Shift+Z</code> / <code>Ctrl+Z</code></td><td>1 分钟内撤回文件翻译，自动清理创建的目录（Ctrl+Z 仅在焦点不在文本输入区时生效）</td></tr><tr><td>文件翻译开关</td><td><code>Alt+Shift+D</code></td><td>快速开启/关闭文件路径翻译</td></tr><tr><td>切换翻译服务</td><td><code>Alt+Shift+S</code></td><td>在 7 种翻译服务间快速切换</td></tr></tbody></table><h2 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h2><ul><li><strong>多语言自动检测</strong>：无需指定源语言，任意非英文字符均可识别</li><li><strong>8 种命名格式</strong>：camelCase、PascalCase、snake_case、CONSTANT_CASE、param-case、Header-Case、Capital Case、no case</li><li><strong>多翻译服务</strong>：OpenAI、谷歌翻译、Bing/Azure、DeepLX、百度翻译、腾讯翻译君、拼音</li><li><strong>自动降级</strong>：翻译失败按优先级降级到下一个服务，最终拼音兜底，保证翻译永不失败</li><li><strong>超时保护</strong>：全局 10 秒翻译超时，不会卡住编辑器</li><li><strong>零配置可用</strong>：默认拼音服务开箱即用，无需任何 API Key</li></ul><h2 id="支持的语言" tabindex="-1">支持的语言 <a class="header-anchor" href="#支持的语言" aria-label="Permalink to &quot;支持的语言&quot;">​</a></h2><p>插件会自动检测以下语言并翻译为英文：</p><table tabindex="0"><thead><tr><th>语言</th><th>示例</th></tr></thead><tbody><tr><td>中文</td><td>用户名称 → userName</td></tr><tr><td>日文</td><td>ユーザー名 → userName</td></tr><tr><td>韩文</td><td>사용자 이름 → userName</td></tr><tr><td>俄文</td><td>Имя пользователя → userName</td></tr><tr><td>其他</td><td>任何非英文字符</td></tr></tbody></table><h2 id="命名格式说明" tabindex="-1">命名格式说明 <a class="header-anchor" href="#命名格式说明" aria-label="Permalink to &quot;命名格式说明&quot;">​</a></h2><h3 id="文件翻译格式" tabindex="-1">文件翻译格式 <a class="header-anchor" href="#文件翻译格式" aria-label="Permalink to &quot;文件翻译格式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>格式</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>camelCase</td><td>userName</td><td>小驼峰，首字母小写</td></tr><tr><td>PascalCase</td><td>UserName</td><td>大驼峰，首字母大写</td></tr><tr><td>snake_case</td><td>user_name</td><td>下划线分隔，全小写</td></tr><tr><td>CONSTANT_CASE</td><td>USER_NAME</td><td>下划线分隔，全大写</td></tr><tr><td>param-case</td><td>user-name</td><td>连字符分隔，全小写</td></tr><tr><td>Header-Case</td><td>User-Name</td><td>连字符分隔，首字母大写</td></tr></tbody></table><h3 id="选中文本翻译额外格式" tabindex="-1">选中文本翻译额外格式 <a class="header-anchor" href="#选中文本翻译额外格式" aria-label="Permalink to &quot;选中文本翻译额外格式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>格式</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>Capital Case</td><td>User Name</td><td>首字母大写，空格分隔</td></tr><tr><td>no case</td><td>user name</td><td>全小写，空格分隔</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/hias-variable-translator/guide/quickstart">快速开始</a> - 安装并上手使用</li><li><a href="/hias-variable-translator/guide/features">功能说明</a> - 了解各功能的详细行为</li><li><a href="/hias-variable-translator/guide/config">配置项</a> - 完整配置参考</li><li><a href="/hias-variable-translator/guide/services">翻译服务</a> - 各翻译服务的申请与配置</li></ul>',17)])])}const m=a(i,[["render",l]]);export{b as __pageData,m as default};
